contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint256 priceLimit) public payable {
        require(true);
        uint256 before = c._PRICE_LIMIT_(); if (__ESBMC_reverted()) return;
        bool reverted;
        c.adjustPriceLimit(priceLimit); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted && c._PRICE_LIMIT_() == before);
    }
    receive() external payable {}
}

