pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {GSPFunding} from "../src/GSPFunding.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    GSPFunding c;

    function setUp() public {
        c = new GSPFunding();
    }

    function _run(uint256 priceLimit) internal {
        vm.assume(true);
        uint256 before;
        try c._PRICE_LIMIT_() returns (uint256 __r) { before = __r; } catch { return; }
        bool reverted;
        try c.adjustPriceLimit(priceLimit) { reverted = false; }
        catch { reverted = true; }
        assertTrue(reverted && c._PRICE_LIMIT_() == before);
    }

    function testFuzz_run(uint256 priceLimit) public {
        _run(priceLimit);
    }

    receive() external payable {}
}
